public static class ConfigResource
{
    [McpServerResource(
        UriTemplate = "config://app/settings",
        Name = "App Configuration",
        MimeType = "application/json")]
    [Description("Returns the application configuration data.")]
    public static string GetAppSettings()
    {
        var config = new
        {
            AppName = "McpHttpServer",
            Version = "1.0.0",
            Environment = System.Environment.GetEnvironmentVariable("ASPNETCORE_ENVIRONMENT") ?? "Production",
            Features = new { EnableLogging = true, MaxConnections = 100 }
        };

        return JsonSerializer.Serialize(config, new JsonSerializerOptions { WriteIndented = true });
    }

    [McpServerResource(
        UriTemplate = "config://app/endpoints",
        Name = "API Endpoints",
        MimeType = "application/json")]
    [Description("Returns available API endpoint information.")]
    public static string GetEndpoints()
    {
        var endpoints = new[]
        {
            new { Path = "/mcp", Method = "POST", Description = "MCP HTTP transport endpoint" },
            new { Path = "/mcp/sse", Method = "GET", Description = "MCP SSE transport endpoint" }
        };

        return JsonSerializer.Serialize(endpoints, new JsonSerializerOptions { WriteIndented = true });
    }
}

